{"path":"md/md.go","content":"// Package md implements a small Markdown-subset to HTML converter.
// The exact rules are specified in SPEC.md at the repository root.
package md

import (
	"strings"
)

// ToHTML converts src to HTML following the block and inline rules of the spec.
func ToHTML(src string) string {
	lines := strings.Split(src, "\n")
	for i, l := range lines {
		lines[i] = strings.TrimSuffix(l, "\r")
	}
	return renderBlocks(lines)
}

// ---------- helpers ----------

func isBlank(s string) bool { return strings.TrimSpace(s) == "" }

func trimTrailSpace(s string) string { return strings.TrimRight(s, " ") }

func isAlnum(r byte) bool {
	return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9'
}

// ---------- blocks ----------

// renderBlocks renders a list of lines as a sequence of block elements.
// Each block element is followed by "\n".
func renderBlocks(lines []string) string {
	var b strings.Builder
	i := 0
	n := len(lines)
	for i < n {
		line := lines[i]

		if isBlank(line) {
			i++
			continue
		}

		// Fenced code block.
		if strings.HasPrefix(line, "```") {
			info := strings.TrimSpace(line[3:])
			var content []string
			j := i + 1
			for j < n && strings.TrimRight(lines[j], " ") != "```" {
				content = append(content, lines[j])
				j++
			}
			body := strings.Join(content, "\n")
			if len(content) > 0 {
				body += "\n"
			}
			class := ""
			if info != "" {
				class = ` class="language-` + info + `"`
			}
			b.WriteString("<pre><code" + class + ">" + body + "</code></pre>\n")
			i = j
			continue
		}

		// Heading.
		hl := 0
		for hl < len(line) && line[hl] == '#' && hl < 6 {
			hl++
		}
		if hl > 0 && hl < len(line) && line[hl] == '#' {
			hl++ // more than six hashes: not a heading
		}
		isHeading := false
		text := ""
		if hl > 0 && hl <= 6 {
			if hl == len(line) {
				isHeading = true // "#", "##", ... alone
			} else if line[hl] == ' ' {
				isHeading = true
				text = line[hl+1:]
			}
		}
		if isHeading {
			text = cleanHeadingText(text)
			b.WriteString("<h" + itoa(hl) + ">" + renderInline(text) + "</h" + itoa(hl) + ">\n")
			i++
			continue
		}

		// Horizontal rule.
		if isHR(line) {
			b.WriteString("<hr />\n")
			i++
			continue
		}

		// Blockquote.
		if strings.HasPrefix(line, ">") {
			var inner []string
			j := i
			for j < n && strings.HasPrefix(lines[j], ">") {
				rest := lines[j][1:]
				if strings.HasPrefix(rest, " ") {
					rest = rest[1:]
				}
				inner = append(inner, rest)
				j++
			}
			b.WriteString("<blockquote>\n" + renderBlocks(inner) + "</blockquote>\n")
			i = j
			continue
		}

		// List item at indentation 0.
		marker, ok := listItemMarker(line)
		if ok {
			items, next := collectList(lines, i)
			b.WriteString(renderList(items))
			i = next
			continue
		}

		// Paragraph.
		var para []string
		j := i
		for j < n {
			l := lines[j]
			if isBlank(l) ||
				strings.HasPrefix(l, "```") ||
				isHeadingLine(l) ||
				isHR(l) ||
				strings.HasPrefix(l, ">") ||
				listItemMarkerAt0(l) {
				break
			}
			para = append(para, strings.TrimLeft(l, " "))
			j++
		}
		b.WriteString("<p>" + renderInline(strings.Join(para, "\n")) + "</p>\n")
		i = j
	}
	return b.String()
}

func isHeadingLine(line string) bool {
	hl := 0
	for hl < len(line) && line[hl] == '#' && hl < 6 {
		hl++
	}
	if hl == 0 || hl > 6 {
		return false
	}
	if hl == len(line) {
		return true
	}
	return line[hl] == ' '
}

func isHR(line string) bool {
	if len(line) < 3 {
		return false
	}
	c := line[0]
	if c != '-' && c != '*' && c != '_' {
		return false
	}
	for _, r := range line {
		if r != rune(c) {
			return false
		}
	}
	return true
}

// listItemMarker returns the marker text ("-", "*", "+", or "N.") and whether
// the line starts with a list-item marker at indentation 0.
func listItemMarker(line string) (string, bool) {
	switch {
	case strings.HasPrefix(line, "- "),
		strings.HasPrefix(line, "* "),
		strings.HasPrefix(line, "+ "):
		return line[:2], true
	}
	i := 0
	for i < len(line) && line[i] >= '0' && line[i] <= '9' {
		i++
	}
	if i > 0 && i < len(line) && line[i] == '.' && i+1 < len(line) && line[i+1] == ' ' {
		return line[:i+1], true
	}
	return "", false
}

func listItemMarkerAt0(line string) bool {
	_, ok := listItemMarker(line)
	return ok
}

type listItem struct {
	num     int
	text    string // item text plus continuation lines joined with "\n"
	nested  []*listItem
	hasNest bool
}

// collectList gathers consecutive items of one kind starting at index i.
func collectList(lines []string, i int) ([]*listItem, int) {
	kind := "u"
	if _, ok := listItemMarker(lines[i]); ok && !strings.HasSuffix(listItemMarker(lines[i]), ".") {
		kind = "u"
	} else {
		kind = "o"
	}
	var items []*listItem
	j := i
	for j < len(lines) {
		line := lines[j]
		if isBlank(line) {
			break
		}
		indent := leadingSpaces(line)
		if indent == 0 {
			m, ok := listItemMarker(line)
			if !ok {
				break
			}
			if (strings.HasSuffix(m, ".")) != (kind == "o") {
				break
			}
			item := &listItem{num: parseNum(m), text: line[len(m):]}
			items = append(items, item)
			j++
			// Continuation lines: indented by 2 or more spaces.
			for j < len(lines) {
				l := lines[j]
				if isBlank(l) {
					break
				}
				sp := leadingSpaces(l)
				if sp < 2 {
					break
				}
				trimmed := strings.TrimLeft(l, " ")
				if nm, ok := listItemMarker(trimmed); ok {
					sub := &listItem{num: parseNum(nm), text: trimmed[len(nm):]}
					item.nested = append(item.nested, sub)
					item.hasNest = true
					j++
					// Continuations of the nested item.
					for j < len(lines) {
						l2 := lines[j]
						if isBlank(l2) {
							break
						}
						sp2 := leadingSpaces(l2)
						if sp2 < 2 {
							break
						}
						t2 := strings.TrimLeft(l2, " ")
						if _, ok := listItemMarker(t2); ok {
							break
						}
						sub.text += "\n" + t2
						j++
					}
				} else {
					item.text += "\n" + trimmed
					j++
				}
			}
			continue
		}
		// Indentation 1: not an item and not a continuation -> ends the list.
		break
	}
	return items, j
}

func leadingSpaces(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func parseNum(marker string) int {
	s := strings.TrimSuffix(marker, ".")
	n := 0
	for _, r := range s {
		n = n*10 + int(r-'0')
	}
	return n
}

func renderList(items []*listItem) string {
	tag := "ul"
	if strings.HasSuffix(listItemMarker(""), "") || items[0].num != 1 {
		tag = "ol"
	}
	// Determine tag from the first item's marker kind via its number usage:
	// we re-derive from the marker stored implicitly; ordered lists were collected only for "N. " markers.
	return renderListItems(tag, items)
}

// renderListWithKind renders items with the given tag ("ul"/"ol").
func renderListWithKind(tag string, items []*listItem) string {
	var b strings.Builder
	if tag == "ol" {
		if items[0].num != 1 {
			b.WriteString(`<ol start="` + itoa(items[0].num) + `">`)
		} else {
			b.WriteString("<ol>")
		}
	} else {
		b.WriteString("<ul>")
	}
	for _, it := range items {
		b.WriteString("\n<li>" + renderInline(it.text))
		if it.hasNest {
			b.WriteString("\n" + renderListWithKind("ul", it.nested) + "\n")
		}
		b.WriteString("</li>")
	}
	b.WriteString("\n</" + tag + ">\n")
	return b.String()
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	digits := []byte{}
	for n > 0 {
		digits = append([]byte{byte('0' + n%10)}, digits...)
		n /= 10
	}
	return string(digits)
}

// cleanHeadingText removes trailing spaces and a trailing run of '#' preceded
// by a space (repeatedly).
func cleanHeadingText(s string) string {
	for {
		s = strings.TrimRight(s, " ")
		if strings.HasSuffix(s, "#") {
			idx := len(s) - 1
			for idx > 0 && s[idx-1] == '#' {
				idx--
			}
			if idx == 0 || s[idx-1] == ' ' {
				s = s[:idx]
				continue
			}
		}
		return s
	}
}
